oxy_webhelp_navlinks = {"tocId-d39536e65411":{"topics":[{"title":"Editing reports using the wizard","shortdesc":"<p class=\"shortdesc\">Use the Report Creation Wizard to edit a saved report's column, filter, and chart         settings.<\/p>","href":"saas\/common\/editing_a_report_in_wizard.html","attributes":{"data-id":"editing_a_report_in_wizard"},"menu":{"hasChildren":false},"tocID":"editing_a_report_in_wizard-d39536e65412","topics":[]},{"title":"Apply report filters","shortdesc":"<p class=\"shortdesc\">You can use report filters to select the relevant data for each <span class=\"ph\">RSC<\/span>         report. Report filters apply to the entire report, including all tables and         charts.<\/p>","href":"saas\/common\/apply_report_filters.html","attributes":{"data-id":"apply_report_filters"},"menu":{"hasChildren":false},"tocID":"apply_report_filters-d39536e65423","topics":[]},{"title":"Apply groupings to report charts","shortdesc":"<p class=\"shortdesc\">Groupings in report charts combine data into aggregated values, so you can compare         results across clusters, object types, locations, and more.<\/p>","href":"saas\/common\/apply_groupings_report_charts.html","attributes":{"data-id":"apply_groupings_report_charts"},"menu":{"hasChildren":false},"tocID":"apply_groupings_report_charts-d39536e65437","topics":[]},{"title":"Report date and time settings","shortdesc":"<p class=\"shortdesc\">You can configure the time zone, date format, and time format to control how         timestamps appear in reports.<\/p>","href":"saas\/common\/report_date_time_settings.html","attributes":{"data-id":"report_date_time_settings"},"menu":{"hasChildren":false},"tocID":"report_date_time_settings-d39536e65448","next":"report_date_time_settings-d39536e65448"}]}};